function validate([currentState]) {
  if (typeof currentState !== 'string' || currentState.length < 1 || currentState.length > 500) return 'currentState has 1 to 500 characters.';
  if (!/^[+-]+$/.test(currentState)) return "currentState may only contain '+' and '-'.";
  return null;
}

