function generatePossibleNextMoves(currentState) {
  const moves = [];

  for (let i = 1; i < currentState.length; i++) {
    if (currentState[i - 1] === '+' && currentState[i] === '+') {
      const before = currentState.slice(0, i - 1);
      const after = currentState.slice(i + 1);
      moves.push(before + '--' + after);
    }
  }
  return moves;
}

