function generatePossibleNextMoves(currentState) {
  // Blank out every adjacent pair, then keep the results where exactly two '+' signs turned into '-'.
  const out = [];
  const chars = currentState.split('');
  for (let i = 0; i + 1 < chars.length; i++) {
    const next = chars.map((c, j) => (j === i || j === i + 1 ? '-' : c));
    let flipped = 0;
    for (let j = 0; j < chars.length; j++) if (chars[j] === '+' && next[j] === '-') flipped++;
    if (flipped === 2) out.push(next.join(''));
  }
  return out;
}

