function generate(rand, size) {
  const n = size === 'large' ? 400 + Math.floor(rand() * 101) : 1 + Math.floor(rand() * 10);
  const plus = rand() < 0.2 ? 1 : 0.3 + rand() * 0.6;
  let currentState = '';
  for (let i = 0; i < n; i++) currentState += rand() < plus ? '+' : '-';
  return [currentState];
}
